### Tested versions

Tested on 4.3

### System information

Godot v4.3.stable.mono - Windows 10.0.19045 - Vulkan (Forward+) - dedicated NVIDIA GeForce RTX 3080 (NVIDIA; 32.0.15.6603) - 12th Gen Intel(R) Core(TM) i7-12700KF (12 Threads)

### Issue description

When alternating between enabled and disabled states memory usage goes up incrementally and when left long enough will crash the project 

### Steps to reproduce

The following code will reproduce the problem, albeit at a much slower scale than in my actual project.

```cs
using Godot;
using System;
using System.Collections.Generic;

public partial class BodySetDisabledTest : Node2D
{
    [Export]
    RectangleShape2D TileCollisionShape { get; set; }

    List<StaticBody2D> StaticBodies { get; set; } = new List<StaticBody2D>();

	[Export]
	Vector2I Res { get; set; }

    [Export]
    int NumOfStaticBodies { get; set; } = 512;

    bool enabled = false;
    [Export]
    public double TimeToSwitch { get; set; } = 1f;
    public double TimeSinceSwitch = 0f;
    // Called when the node enters the scene tree for the first time.
    public override void _Ready()
	{
        for (int i = 0; i < NumOfStaticBodies; i++)
        {
            var t = new StaticBody2D();
            t.Position = new Vector2(i * 50, 0);
            AddChild(t);
            StaticBodies.Add(t);

            for (int y = 0; y < Res.Y; y++)
            {
                for (int x = 0; x < Res.X; x++)
                {
                    PhysicsServer2D.BodyAddShape(t.GetRid(), TileCollisionShape.GetRid(), new Transform2D(0, new Vector2(x, y)), true); // init body shapes, defaulting to disabled
                }
            }
        }
	}

	// Called every frame. 'delta' is the elapsed time since the previous frame.
	public override void _Process(double delta)
	{
        if (TimeSinceSwitch < 0f)
        {
            TimeSinceSwitch = TimeToSwitch;

            if (enabled) Disable();
            else Enable();

            enabled = !enabled;
        }
        TimeSinceSwitch -= delta;
	}



	private void Enable()
	{
        GD.Print("Enabled");
        StaticBodies.ForEach(b =>
        {
            for (int y = 0; y < Res.Y; y++)
            {
                for (int x = 0; x < Res.X; x++)
                {
                    var index = x + y * Res.X;
                    PhysicsServer2D.BodySetShapeDisabled(b.GetRid(), index, false);
                }
            }
        });
    }


    private void Disable()
    {
        GD.Print("Disabled");
        StaticBodies.ForEach(b =>
        {
            for (int y = 0; y < Res.Y; y++)
            {
                for (int x = 0; x < Res.X; x++)
                {
                    var index = x + y * Res.X;
                    PhysicsServer2D.BodySetShapeDisabled(b.GetRid(), index, true);
                }
            }
        });
    }
}
```

